'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

const NOTIFICATION_COOKIE = 'notifications-enabled'

export async function toggleNotificationPreference(formData?: FormData) {
  const cookieStore = await cookies()
  const currentValue = formData?.get('current')?.toString() ?? cookieStore.get(NOTIFICATION_COOKIE)?.value ?? 'off'
  const newValue = currentValue === 'on' ? 'off' : 'on'

  cookieStore.set(NOTIFICATION_COOKIE, newValue, {
    path: '/',
    maxAge: 60 * 60 * 24 * 365, // 1 year
  })

  refresh()
}

